import React, { useState, useEffect } from 'react';
import './App.css';
import Header from './components/Header';
import ScenarioSelector from './components/ScenarioSelector';
import DataTable from './components/DataTable';
import ConfusionMatrix from './components/ConfusionMatrix';
import MetricsDisplay from './components/MetricsDisplay';
import ExamGuide from './components/ExamGuide';

function App() {
  const [scenario, setScenario] = useState('cancer');
  const [confusionMatrix, setConfusionMatrix] = useState({ TP: 0, FP: 0, FN: 0, TN: 0 });

  // Scenario configurations with real examples
  const scenarios = {
    cancer: {
      name: 'Cancer Detection',
      description: 'Medical diagnosis where missing cancer (false negative) is catastrophic',
      totalSamples: 1000,
      positiveRate: 0.1,
      optimalMetric: 'Recall',
      color: '#e74c3c',
      realExample: 'A hospital screens 1,000 patients. 100 actually have cancer.',
      whyThisMetric: 'Missing a cancer diagnosis (False Negative) can be fatal. We prioritize RECALL to catch all cancer cases, even if it means more false alarms.',
      costAnalysis: {
        FN: 'Patient dies - CATASTROPHIC',
        FP: 'Extra tests needed - Acceptable',
        optimal: 'Maximize Recall (minimize FN)'
      },
      samples: [
        { id: 1, actual: 'Cancer', predicted: 'Cancer', result: 'TP', explanation: 'Correctly identified cancer - patient gets treatment' },
        { id: 2, actual: 'Healthy', predicted: 'Cancer', result: 'FP', explanation: 'False alarm - patient gets extra tests (acceptable cost)' },
        { id: 3, actual: 'Cancer', predicted: 'Healthy', result: 'FN', explanation: 'MISSED CANCER - patient goes untreated (CATASTROPHIC)' },
        { id: 4, actual: 'Healthy', predicted: 'Healthy', result: 'TN', explanation: 'Correctly identified healthy patient' }
      ]
    },
    fraud: {
      name: 'Fraud Detection',
      description: 'Balance between catching fraud and not annoying legitimate customers',
      totalSamples: 10000,
      positiveRate: 0.02,
      optimalMetric: 'F1-Score',
      color: '#f39c12',
      realExample: 'A bank processes 10,000 transactions. 200 are fraudulent.',
      whyThisMetric: 'Both errors are costly: Missing fraud loses money, blocking legitimate transactions annoys customers. We use F1-SCORE to balance both.',
      costAnalysis: {
        FN: 'Fraud succeeds - Lose money',
        FP: 'Block legitimate transaction - Angry customer',
        optimal: 'Balance with F1-Score'
      },
      samples: [
        { id: 1, actual: 'Fraud', predicted: 'Fraud', result: 'TP', explanation: 'Caught fraud - transaction blocked, money saved' },
        { id: 2, actual: 'Legitimate', predicted: 'Fraud', result: 'FP', explanation: 'Blocked legitimate transaction - customer frustrated' },
        { id: 3, actual: 'Fraud', predicted: 'Legitimate', result: 'FN', explanation: 'Missed fraud - money stolen from account' },
        { id: 4, actual: 'Legitimate', predicted: 'Legitimate', result: 'TN', explanation: 'Normal transaction processed smoothly' }
      ]
    },
    spam: {
      name: 'Spam Filter',
      description: 'Avoid marking legitimate emails as spam (minimize false positives)',
      totalSamples: 5000,
      positiveRate: 0.3,
      optimalMetric: 'Precision',
      color: '#3498db',
      realExample: 'An email system processes 5,000 emails. 1,500 are spam.',
      whyThisMetric: 'Marking important emails as spam (False Positive) is worse than letting spam through. We prioritize PRECISION to avoid false positives.',
      costAnalysis: {
        FN: 'Spam in inbox - Minor annoyance',
        FP: 'Important email missed - SERIOUS',
        optimal: 'Maximize Precision (minimize FP)'
      },
      samples: [
        { id: 1, actual: 'Spam', predicted: 'Spam', result: 'TP', explanation: 'Correctly filtered spam - inbox stays clean' },
        { id: 2, actual: 'Important', predicted: 'Spam', result: 'FP', explanation: 'Job offer marked as spam - MISSED OPPORTUNITY' },
        { id: 3, actual: 'Spam', predicted: 'Important', result: 'FN', explanation: 'Spam in inbox - user can delete (minor annoyance)' },
        { id: 4, actual: 'Important', predicted: 'Important', result: 'TN', explanation: 'Important email delivered correctly' }
      ]
    }
  };

  // Calculate metrics from confusion matrix
  const calculateMetrics = () => {
    const { TP, FP, FN, TN } = confusionMatrix;
    const total = TP + FP + FN + TN;

    const accuracy = (TP + TN) / total;
    const precision = TP / (TP + FP) || 0;
    const recall = TP / (TP + FN) || 0;
    const f1 = 2 * (precision * recall) / (precision + recall) || 0;
    const specificity = TN / (TN + FP) || 0;

    return { accuracy, precision, recall, f1, specificity };
  };

  // Update confusion matrix based on threshold
  const updateConfusionMatrix = (newThreshold) => {
    const config = scenarios[scenario];
    const total = config.totalSamples;
    const actualPositives = Math.round(total * config.positiveRate);
    const actualNegatives = total - actualPositives;

    // Simulate model performance based on threshold
    const sensitivity = 0.95 - (newThreshold - 0.5) * 0.4;
    const specificity = 0.85 + (newThreshold - 0.5) * 0.3;

    const TP = Math.round(actualPositives * Math.max(0.1, Math.min(0.99, sensitivity)));
    const FN = actualPositives - TP;
    const TN = Math.round(actualNegatives * Math.max(0.1, Math.min(0.99, specificity)));
    const FP = actualNegatives - TN;

    setConfusionMatrix({ TP, FP, FN, TN });
  };

  const handleScenarioChange = (newScenario) => {
    setScenario(newScenario);
    setThreshold(0.5);
    // Update confusion matrix based on scenario
    const config = scenarios[newScenario];
    const actualPositives = Math.round(config.totalSamples * config.positiveRate);
    const actualNegatives = config.totalSamples - actualPositives;

    const TP = Math.round(actualPositives * 0.85);
    const FN = actualPositives - TP;
    const TN = Math.round(actualNegatives * 0.95);
    const FP = actualNegatives - TN;

    setConfusionMatrix({ TP, FP, FN, TN });
  };

  const handleThresholdChange = (newThreshold) => {
    setThreshold(newThreshold);
    updateConfusionMatrix(newThreshold);
  };

  const metrics = calculateMetrics();

  return (
    <div className="App">
      <Header />

      <div className="container">
        <ScenarioSelector 
          scenarios={scenarios}
          currentScenario={scenario}
          onScenarioChange={handleScenarioChange}
        />

        <div className="main-content">
          <div className="left-panel">
            <SampleExplorer 
              scenario={scenarios[scenario]}
              color={scenarios[scenario].color}
            />

            <ConfusionMatrix 
              matrix={confusionMatrix}
              color={scenarios[scenario].color}
            />

            <ThresholdSlider 
              threshold={threshold}
              onThresholdChange={handleThresholdChange}
              color={scenarios[scenario].color}
            />

            <MetricsDisplay 
              metrics={metrics}
              optimalMetric={scenarios[scenario].optimalMetric}
              color={scenarios[scenario].color}
            />
          </div>

          <div className="right-panel">
            <ROCCurve 
              confusionMatrix={confusionMatrix}
              threshold={threshold}
              color={scenarios[scenario].color}
            />

            <ExamGuide 
              scenario={scenarios[scenario]}
              metrics={metrics}
              confusionMatrix={confusionMatrix}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
